        impl < 'i , R : RuleType > ParserState < 'i , R > { # [doc = " Allocates a fresh `ParserState` object to the heap and returns the owned `Box`. This `Box`"] # [doc = " will be passed from closure to closure based on the needs of the specified `Parser`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " let input = \"\";"] # [doc = " let state: Box<pest::ParserState<&str>> = pest::ParserState::new(input);"] # [doc = " ```"] pub fn new (input : & 'i str) -> Box < Self > { Box :: new (ParserState { position : Position :: from_start (input) , queue : vec ! [] , lookahead : Lookahead :: None , pos_attempts : vec ! [] , neg_attempts : vec ! [] , attempt_pos : 0 , atomicity : Atomicity :: NonAtomic , stack : Stack :: new () , call_tracker : Default :: default () , parse_attempts : ParseAttempts :: new () , }) } # [doc = " Get all parse attempts after process of parsing is finished."] pub fn get_parse_attempts (& self) -> & ParseAttempts < R > { & self . parse_attempts } # [doc = " Returns a reference to the current `Position` of the `ParserState`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {"] # [doc = "     ab"] # [doc = " }"] # [doc = ""] # [doc = " let input = \"ab\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let position = state.position();"] # [doc = " assert_eq!(position.pos(), 0);"] # [doc = " ```"] pub fn position (& self) -> & Position < 'i > { & self . position } # [doc = " Returns the current atomicity of the `ParserState`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # use pest::Atomicity;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {"] # [doc = "     ab"] # [doc = " }"] # [doc = ""] # [doc = " let input = \"ab\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let atomicity = state.atomicity();"] # [doc = " assert_eq!(atomicity, Atomicity::NonAtomic);"] # [doc = " ```"] pub fn atomicity (& self) -> Atomicity { self . atomicity } # [inline] fn inc_call_check_limit (mut self : Box < Self >) -> ParseResult < Box < Self > > { if self . call_tracker . limit_reached () { return Err (self) ; } self . call_tracker . increment_depth () ; Ok (self) } # [inline] fn reached_call_limit (& self) -> bool { self . call_tracker . limit_reached () } # [doc = " Wrapper needed to generate tokens. This will associate the `R` type rule to the closure"] # [doc = " meant to match the rule."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {"] # [doc = "     a"] # [doc = " }"] # [doc = ""] # [doc = " let input = \"a\";"] # [doc = " let pairs: Vec<_> = pest::state(input, |state| {"] # [doc = "     state.rule(Rule::a, |s| Ok(s))"] # [doc = " }).unwrap().collect();"] # [doc = ""] # [doc = " assert_eq!(pairs.len(), 1);"] # [doc = " ```"] # [inline] pub fn rule < F > (mut self : Box < Self > , rule : R , f : F) -> ParseResult < Box < Self > > where F : FnOnce (Box < Self >) -> ParseResult < Box < Self > > , { self = self . inc_call_check_limit () ? ; let actual_pos = self . position . pos () ; let index = self . queue . len () ; let (pos_attempts_index , neg_attempts_index) = if actual_pos == self . attempt_pos { (self . pos_attempts . len () , self . neg_attempts . len ()) } else { (0 , 0) } ; if self . lookahead == Lookahead :: None && self . atomicity != Atomicity :: Atomic { self . queue . push (QueueableToken :: Start { end_token_index : 0 , input_pos : actual_pos , }) ; } let attempts = self . attempts_at (actual_pos) ; let mut remember_call_stacks_number = self . parse_attempts . call_stacks_number () ; let remember_max_position = self . parse_attempts . max_position ; let result = f (self) ; let mut try_add_rule_to_stack = | new_state : & mut Box < ParserState < '_ , R > > | { if new_state . parse_attempts . max_position > remember_max_position { remember_call_stacks_number = 0 ; } if ! matches ! (new_state . atomicity , Atomicity :: Atomic) { new_state . parse_attempts . try_add_new_stack_rule (rule , remember_call_stacks_number) ; } } ; match result { Ok (mut new_state) => { if new_state . lookahead == Lookahead :: Negative { new_state . track (rule , actual_pos , pos_attempts_index , neg_attempts_index , attempts ,) ; } if new_state . lookahead == Lookahead :: None && new_state . atomicity != Atomicity :: Atomic { let new_index = new_state . queue . len () ; match new_state . queue [index] { QueueableToken :: Start { ref mut end_token_index , .. } => * end_token_index = new_index , _ => unreachable ! () , } ; let new_pos = new_state . position . pos () ; new_state . queue . push (QueueableToken :: End { start_token_index : index , rule , tag : None , input_pos : new_pos , }) ; } if new_state . parse_attempts . enabled { try_add_rule_to_stack (& mut new_state) ; } Ok (new_state) } Err (mut new_state) => { if new_state . lookahead != Lookahead :: Negative { new_state . track (rule , actual_pos , pos_attempts_index , neg_attempts_index , attempts ,) ; if new_state . parse_attempts . enabled { try_add_rule_to_stack (& mut new_state) ; } } if new_state . lookahead == Lookahead :: None && new_state . atomicity != Atomicity :: Atomic { new_state . queue . truncate (index) ; } Err (new_state) } } } # [doc = " Tag current node"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Try to recognize the one specified in a set of characters"] # [doc = ""] # [doc = " ```"] # [doc = " use pest::{state, ParseResult, ParserState, iterators::Pair};"] # [doc = " #[allow(non_camel_case_types)]"] # [doc = " #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {"] # [doc = "     character,"] # [doc = " }"] # [doc = " fn mark_c(state: Box<ParserState<Rule>>) -> ParseResult<Box<ParserState<Rule>>> {"] # [doc = "     state.sequence(|state| {"] # [doc = "         character(state)"] # [doc = "             .and_then(|state| character(state))"] # [doc = "             .and_then(|state| character(state))"] # [doc = "             .and_then(|state| state.tag_node(\"c\"))"] # [doc = "             .and_then(|state| character(state))"] # [doc = "     })"] # [doc = " }"] # [doc = " fn character(state: Box<ParserState<Rule>>) -> ParseResult<Box<ParserState<Rule>>> {"] # [doc = "     state.rule(Rule::character, |state| state.match_range('a'..'z'))"] # [doc = " }"] # [doc = ""] # [doc = " let input = \"abcd\";"] # [doc = " let pairs = state(input, mark_c).unwrap();"] # [doc = " // find all node tag as `c`"] # [doc = " let find: Vec<Pair<Rule>> = pairs.filter(|s| s.as_node_tag() == Some(\"c\")).collect();"] # [doc = " assert_eq!(find[0].as_str(), \"c\")"] # [doc = " ```"] # [inline] pub fn tag_node (mut self : Box < Self > , tag : & 'i str) -> ParseResult < Box < Self > > { if let Some (QueueableToken :: End { tag : old , .. }) = self . queue . last_mut () { * old = Some (tag) } Ok (self) } # [doc = " Get number of allowed rules attempts + prohibited rules attempts."] fn attempts_at (& self , pos : usize) -> usize { if self . attempt_pos == pos { self . pos_attempts . len () + self . neg_attempts . len () } else { 0 } } fn track (& mut self , rule : R , pos : usize , pos_attempts_index : usize , neg_attempts_index : usize , prev_attempts : usize ,) { if self . atomicity == Atomicity :: Atomic { return ; } let curr_attempts = self . attempts_at (pos) ; if curr_attempts > prev_attempts && curr_attempts - prev_attempts == 1 { return ; } if pos == self . attempt_pos { self . pos_attempts . truncate (pos_attempts_index) ; self . neg_attempts . truncate (neg_attempts_index) ; } if pos > self . attempt_pos { self . pos_attempts . clear () ; self . neg_attempts . clear () ; self . attempt_pos = pos ; } let attempts = if self . lookahead != Lookahead :: Negative { & mut self . pos_attempts } else { & mut self . neg_attempts } ; if pos == self . attempt_pos { attempts . push (rule) ; } } # [doc = " Starts a sequence of transformations provided by `f` from the `Box<ParserState>`. Returns"] # [doc = " the same `Result` returned by `f` in the case of an `Ok`, or `Err` with the current"] # [doc = " `Box<ParserState>` otherwise."] # [doc = ""] # [doc = " This method is useful to parse sequences that only match together which usually come in the"] # [doc = " form of chained `Result`s with"] # [doc = " [`Result::and_then`](https://doc.rust-lang.org/std/result/enum.Result.html#method.and_then)."] # [doc = ""] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {"] # [doc = "     a"] # [doc = " }"] # [doc = ""] # [doc = " let input = \"a\";"] # [doc = " let pairs: Vec<_> = pest::state(input, |state| {"] # [doc = "     state.sequence(|s| {"] # [doc = "         s.rule(Rule::a, |s| Ok(s)).and_then(|s| {"] # [doc = "             s.match_string(\"b\")"] # [doc = "         })"] # [doc = "     }).or_else(|s| {"] # [doc = "         Ok(s)"] # [doc = "     })"] # [doc = " }).unwrap().collect();"] # [doc = ""] # [doc = " assert_eq!(pairs.len(), 0);"] # [doc = " ```"] # [inline] pub fn sequence < F > (mut self : Box < Self > , f : F) -> ParseResult < Box < Self > > where F : FnOnce (Box < Self >) -> ParseResult < Box < Self > > , { self = self . inc_call_check_limit () ? ; let token_index = self . queue . len () ; let initial_pos = self . position ; let result = f (self) ; match result { Ok (new_state) => Ok (new_state) , Err (mut new_state) => { new_state . position = initial_pos ; new_state . queue . truncate (token_index) ; Err (new_state) } } } # [doc = " Repeatedly applies the transformation provided by `f` from the `Box<ParserState>`. Returns"] # [doc = " `Ok` with the updated `Box<ParserState>` returned by `f` wrapped up in an `Err`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {"] # [doc = "     ab"] # [doc = " }"] # [doc = ""] # [doc = " let input = \"aab\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state.repeat(|s| {"] # [doc = "     s.match_string(\"a\")"] # [doc = " });"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 2);"] # [doc = ""] # [doc = " state = pest::ParserState::new(input);"] # [doc = " result = state.repeat(|s| {"] # [doc = "     s.match_string(\"b\")"] # [doc = " });"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 0);"] # [doc = " ```"] # [inline] pub fn repeat < F > (mut self : Box < Self > , mut f : F) -> ParseResult < Box < Self > > where F : FnMut (Box < Self >) -> ParseResult < Box < Self > > , { self = self . inc_call_check_limit () ? ; let mut result = f (self) ; loop { match result { Ok (state) => result = f (state) , Err (state) => return Ok (state) , } ; } } # [doc = " Optionally applies the transformation provided by `f` from the `Box<ParserState>`. Returns"] # [doc = " `Ok` with the updated `Box<ParserState>` returned by `f` regardless of the `Result`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {"] # [doc = "     ab"] # [doc = " }"] # [doc = ""] # [doc = " let input = \"ab\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let result = state.optional(|s| {"] # [doc = "     s.match_string(\"ab\")"] # [doc = " });"] # [doc = " assert!(result.is_ok());"] # [doc = ""] # [doc = " state = pest::ParserState::new(input);"] # [doc = " let result = state.optional(|s| {"] # [doc = "     s.match_string(\"ac\")"] # [doc = " });"] # [doc = " assert!(result.is_ok());"] # [doc = " ```"] # [inline] pub fn optional < F > (mut self : Box < Self > , f : F) -> ParseResult < Box < Self > > where F : FnOnce (Box < Self >) -> ParseResult < Box < Self > > , { self = self . inc_call_check_limit () ? ; match f (self) { Ok (state) | Err (state) => Ok (state) , } } # [doc = " Generic function to handle result of char/string/range parsing"] # [doc = " in order to track (un)expected tokens."] fn handle_token_parse_result (& mut self , start_position : usize , token : ParsingToken , parse_succeeded : bool ,) { let current_pos = self . position . pos () ; if parse_succeeded { if self . lookahead == Lookahead :: Negative { self . parse_attempts . try_add_new_token (token , start_position , current_pos , true) ; } else if current_pos > self . parse_attempts . max_position { self . parse_attempts . nullify_expected_tokens (current_pos) ; } } else if self . lookahead != Lookahead :: Negative { self . parse_attempts . try_add_new_token (token , start_position , current_pos , false) ; } } # [doc = " Attempts to match a single character based on a filter function. Returns `Ok` with the"] # [doc = " updated `Box<ParserState>` if successful, or `Err` with the updated `Box<ParserState>`"] # [doc = " otherwise."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"ab\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let result = state.match_char_by(|c| c.is_ascii());"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 1);"] # [doc = ""] # [doc = " let input = \"❤\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let result = state.match_char_by(|c| c.is_ascii());"] # [doc = " assert!(result.is_err());"] # [doc = " assert_eq!(result.unwrap_err().position().pos(), 0);"] # [doc = " ```"] # [inline] pub fn match_char_by < F > (mut self : Box < Self > , f : F) -> ParseResult < Box < Self > > where F : FnOnce (char) -> bool , { let start_position = self . position . pos () ; let succeeded = self . position . match_char_by (f) ; if self . parse_attempts . enabled { let token = ParsingToken :: BuiltInRule ; self . handle_token_parse_result (start_position , token , succeeded) ; } if succeeded { Ok (self) } else { Err (self) } } # [doc = " Attempts to match the given string. Returns `Ok` with the updated `Box<ParserState>` if"] # [doc = " successful, or `Err` with the updated `Box<ParserState>` otherwise."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"ab\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state.match_string(\"ab\");"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 2);"] # [doc = ""] # [doc = " state = pest::ParserState::new(input);"] # [doc = " result = state.match_string(\"ac\");"] # [doc = " assert!(result.is_err());"] # [doc = " assert_eq!(result.unwrap_err().position().pos(), 0);"] # [doc = " ```"] # [inline] pub fn match_string (mut self : Box < Self > , string : & str) -> ParseResult < Box < Self > > { let start_position = self . position . pos () ; let succeeded = self . position . match_string (string) ; if self . parse_attempts . enabled { let token = ParsingToken :: Sensitive { token : String :: from (string) , } ; self . handle_token_parse_result (start_position , token , succeeded) ; } if succeeded { Ok (self) } else { Err (self) } } # [doc = " Pushes the given literal to the stack, and always returns `Ok(Box<ParserState>)`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"ab\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = ""] # [doc = " let mut result = state.stack_push_literal(\"a\");"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.as_ref().unwrap().position().pos(), 0);"] # [doc = ""] # [doc = " let mut result = result.unwrap().stack_pop();"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 1);"] # [doc = " ```"] # [inline] pub fn stack_push_literal (mut self : Box < Self > , string : impl Into < Cow < 'static , str > > ,) -> ParseResult < Box < Self > > { self . stack . push (SpanOrLiteral :: Literal (string . into () . into ())) ; Ok (self) } # [doc = " Attempts to case-insensitively match the given string. Returns `Ok` with the updated"] # [doc = " `Box<ParserState>` if successful, or `Err` with the updated `Box<ParserState>` otherwise."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"ab\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state.match_insensitive(\"AB\");"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 2);"] # [doc = ""] # [doc = " state = pest::ParserState::new(input);"] # [doc = " result = state.match_insensitive(\"AC\");"] # [doc = " assert!(result.is_err());"] # [doc = " assert_eq!(result.unwrap_err().position().pos(), 0);"] # [doc = " ```"] # [inline] pub fn match_insensitive (mut self : Box < Self > , string : & str) -> ParseResult < Box < Self > > { let start_position : usize = self . position () . pos () ; let succeeded = self . position . match_insensitive (string) ; if self . parse_attempts . enabled { let token = ParsingToken :: Insensitive { token : String :: from (string) , } ; self . handle_token_parse_result (start_position , token , succeeded) ; } if succeeded { Ok (self) } else { Err (self) } } # [doc = " Attempts to match a single character from the given range. Returns `Ok` with the updated"] # [doc = " `Box<ParserState>` if successful, or `Err` with the updated `Box<ParserState>` otherwise."] # [doc = ""] # [doc = " # Caution"] # [doc = " The provided `range` is interpreted as inclusive."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"ab\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state.match_range('a'..'z');"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 1);"] # [doc = ""] # [doc = " state = pest::ParserState::new(input);"] # [doc = " result = state.match_range('A'..'Z');"] # [doc = " assert!(result.is_err());"] # [doc = " assert_eq!(result.unwrap_err().position().pos(), 0);"] # [doc = " ```"] # [inline] pub fn match_range (mut self : Box < Self > , range : Range < char >) -> ParseResult < Box < Self > > { let start_position = self . position () . pos () ; let token = ParsingToken :: Range { start : range . start , end : range . end , } ; let succeeded = self . position . match_range (range) ; if self . parse_attempts . enabled { self . handle_token_parse_result (start_position , token , succeeded) ; } if succeeded { Ok (self) } else { Err (self) } } # [doc = " Attempts to skip `n` characters forward. Returns `Ok` with the updated `Box<ParserState>`"] # [doc = " if successful, or `Err` with the updated `Box<ParserState>` otherwise."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"ab\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state.skip(1);"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 1);"] # [doc = ""] # [doc = " state = pest::ParserState::new(input);"] # [doc = " result = state.skip(3);"] # [doc = " assert!(result.is_err());"] # [doc = " assert_eq!(result.unwrap_err().position().pos(), 0);"] # [doc = " ```"] # [inline] pub fn skip (mut self : Box < Self > , n : usize) -> ParseResult < Box < Self > > { if self . position . skip (n) { Ok (self) } else { Err (self) } } # [doc = " Attempts to skip forward until one of the given strings is found. Returns `Ok` with the"] # [doc = " updated `Box<ParserState>` whether or not one of the strings is found."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"abcd\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state.skip_until(&[\"c\", \"d\"]);"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 2);"] # [doc = " ```"] # [inline] pub fn skip_until (mut self : Box < Self > , strings : & [& str]) -> ParseResult < Box < Self > > { self . position . skip_until (strings) ; Ok (self) } # [doc = " Attempts to match the start of the input. Returns `Ok` with the current `Box<ParserState>`"] # [doc = " if the parser has not yet advanced, or `Err` with the current `Box<ParserState>` otherwise."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"ab\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state.start_of_input();"] # [doc = " assert!(result.is_ok());"] # [doc = ""] # [doc = " state = pest::ParserState::new(input);"] # [doc = " state = state.match_string(\"ab\").unwrap();"] # [doc = " result = state.start_of_input();"] # [doc = " assert!(result.is_err());"] # [doc = " ```"] # [inline] pub fn start_of_input (self : Box < Self >) -> ParseResult < Box < Self > > { if self . position . at_start () { Ok (self) } else { Err (self) } } # [doc = " Attempts to match the end of the input. Returns `Ok` with the current `Box<ParserState>` if"] # [doc = " there is no input remaining, or `Err` with the current `Box<ParserState>` otherwise."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"ab\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state.end_of_input();"] # [doc = " assert!(result.is_err());"] # [doc = ""] # [doc = " state = pest::ParserState::new(input);"] # [doc = " state = state.match_string(\"ab\").unwrap();"] # [doc = " result = state.end_of_input();"] # [doc = " assert!(result.is_ok());"] # [doc = " ```"] # [inline] pub fn end_of_input (self : Box < Self >) -> ParseResult < Box < Self > > { if self . position . at_end () { Ok (self) } else { Err (self) } } # [doc = " Starts a lookahead transformation provided by `f` from the `Box<ParserState>`. It returns"] # [doc = " `Ok` with the current `Box<ParserState>` if `f` also returns an `Ok`, or `Err` with the current"] # [doc = " `Box<ParserState>` otherwise. If `is_positive` is `false`, it swaps the `Ok` and `Err`"] # [doc = " together, negating the `Result`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {"] # [doc = "     a"] # [doc = " }"] # [doc = ""] # [doc = " let input = \"a\";"] # [doc = " let pairs: Vec<_> = pest::state(input, |state| {"] # [doc = "     state.lookahead(true, |state| {"] # [doc = "         state.rule(Rule::a, |s| Ok(s))"] # [doc = "     })"] # [doc = " }).unwrap().collect();"] # [doc = ""] # [doc = " assert_eq!(pairs.len(), 0);"] # [doc = " ```"] # [inline] pub fn lookahead < F > (mut self : Box < Self > , is_positive : bool , f : F) -> ParseResult < Box < Self > > where F : FnOnce (Box < Self >) -> ParseResult < Box < Self > > , { self = self . inc_call_check_limit () ? ; let initial_lookahead = self . lookahead ; self . lookahead = if is_positive { match initial_lookahead { Lookahead :: None | Lookahead :: Positive => Lookahead :: Positive , Lookahead :: Negative => Lookahead :: Negative , } } else { match initial_lookahead { Lookahead :: None | Lookahead :: Positive => Lookahead :: Negative , Lookahead :: Negative => Lookahead :: Positive , } } ; let initial_pos = self . position ; let result = f (self . checkpoint ()) ; let result_state = match result { Ok (mut new_state) => { new_state . position = initial_pos ; new_state . lookahead = initial_lookahead ; Ok (new_state . restore ()) } Err (mut new_state) => { new_state . position = initial_pos ; new_state . lookahead = initial_lookahead ; Err (new_state . restore ()) } } ; if is_positive { result_state } else { match result_state { Ok (state) => Err (state) , Err (state) => Ok (state) , } } } # [doc = " Transformation which stops `Token`s from being generated according to `is_atomic`."] # [doc = " Used as wrapper over `rule` (or even another `atomic`) call."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest::{self, Atomicity};"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {"] # [doc = "     a"] # [doc = " }"] # [doc = ""] # [doc = " let input = \"a\";"] # [doc = " let pairs: Vec<_> = pest::state(input, |state| {"] # [doc = "     state.atomic(Atomicity::Atomic, |s| {"] # [doc = "         s.rule(Rule::a, |s| Ok(s))"] # [doc = "     })"] # [doc = " }).unwrap().collect();"] # [doc = ""] # [doc = " assert_eq!(pairs.len(), 0);"] # [doc = " ```"] # [inline] pub fn atomic < F > (mut self : Box < Self > , atomicity : Atomicity , f : F) -> ParseResult < Box < Self > > where F : FnOnce (Box < Self >) -> ParseResult < Box < Self > > , { self = self . inc_call_check_limit () ? ; let initial_atomicity = self . atomicity ; let should_toggle = self . atomicity != atomicity ; if should_toggle { self . atomicity = atomicity ; } let result = f (self) ; match result { Ok (mut new_state) => { if should_toggle { new_state . atomicity = initial_atomicity ; } Ok (new_state) } Err (mut new_state) => { if should_toggle { new_state . atomicity = initial_atomicity ; } Err (new_state) } } } # [doc = " Evaluates the result of closure `f` and pushes the span of the input consumed from before"] # [doc = " `f` is called to after `f` is called to the stack. Returns `Ok(Box<ParserState>)` if `f` is"] # [doc = " called successfully, or `Err(Box<ParserState>)` otherwise."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"ab\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state.stack_push(|state| state.match_string(\"a\"));"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 1);"] # [doc = " ```"] # [inline] pub fn stack_push < F > (mut self : Box < Self > , f : F) -> ParseResult < Box < Self > > where F : FnOnce (Box < Self >) -> ParseResult < Box < Self > > , { self = self . inc_call_check_limit () ? ; let start = self . position ; let result = f (self) ; match result { Ok (mut state) => { let end = state . position ; state . stack . push (SpanOrLiteral :: Span (start . span (& end))) ; Ok (state) } Err (state) => Err (state) , } } # [doc = " Peeks the top of the stack and attempts to match the string. Returns `Ok(Box<ParserState>)`"] # [doc = " if the string is matched successfully, or `Err(Box<ParserState>)` otherwise."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"aa\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state.stack_push(|state| state.match_string(\"a\")).and_then("] # [doc = "     |state| state.stack_peek()"] # [doc = " );"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 2);"] # [doc = " ```"] # [inline] pub fn stack_peek (self : Box < Self >) -> ParseResult < Box < Self > > { let string = self . stack . peek () . expect ("peek was called on empty stack") . as_borrowed_or_rc () ; self . match_string (string . as_str ()) } # [doc = " Pops the top of the stack and attempts to match the string. Returns `Ok(Box<ParserState>)`"] # [doc = " if the string is matched successfully, or `Err(Box<ParserState>)` otherwise."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"aa\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state.stack_push(|state| state.match_string(\"a\")).and_then("] # [doc = "     |state| state.stack_pop()"] # [doc = " );"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 2);"] # [doc = " ```"] # [inline] pub fn stack_pop (mut self : Box < Self >) -> ParseResult < Box < Self > > { let string = self . stack . pop () . expect ("pop was called on empty stack") . as_borrowed_or_rc () ; self . match_string (string . as_str ()) } # [doc = " Matches part of the state of the stack."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest::{self, MatchDir};"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"abcd cd cb\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state"] # [doc = "     .stack_push(|state| state.match_string(\"a\"))"] # [doc = "     .and_then(|state| state.stack_push(|state| state.match_string(\"b\")))"] # [doc = "     .and_then(|state| state.stack_push(|state| state.match_string(\"c\")))"] # [doc = "     .and_then(|state| state.stack_push(|state| state.match_string(\"d\")))"] # [doc = "     .and_then(|state| state.match_string(\" \"))"] # [doc = "     .and_then(|state| state.stack_match_peek_slice(2, None, MatchDir::BottomToTop))"] # [doc = "     .and_then(|state| state.match_string(\" \"))"] # [doc = "     .and_then(|state| state.stack_match_peek_slice(1, Some(-1), MatchDir::TopToBottom));"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 10);"] # [doc = " ```"] # [inline] pub fn stack_match_peek_slice (mut self : Box < Self > , start : i32 , end : Option < i32 > , match_dir : MatchDir ,) -> ParseResult < Box < Self > > { let range = match constrain_idxs (start , end , self . stack . len ()) { Some (r) => r , None => return Err (self) , } ; if range . end <= range . start { return Ok (self) ; } let mut position = self . position ; let result = { let mut iter_b2t = self . stack [range] . iter () ; let matcher = | span : & SpanOrLiteral < '_ > | position . match_string (span . as_borrowed_or_rc () . as_str ()) ; match match_dir { MatchDir :: BottomToTop => iter_b2t . all (matcher) , MatchDir :: TopToBottom => iter_b2t . rev () . all (matcher) , } } ; if result { self . position = position ; Ok (self) } else { Err (self) } } # [doc = " Matches the full state of the stack."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"abba\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state"] # [doc = "     .stack_push(|state| state.match_string(\"a\"))"] # [doc = "     .and_then(|state| { state.stack_push(|state| state.match_string(\"b\")) })"] # [doc = "     .and_then(|state| state.stack_match_peek());"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 4);"] # [doc = " ```"] # [inline] pub fn stack_match_peek (self : Box < Self >) -> ParseResult < Box < Self > > { self . stack_match_peek_slice (0 , None , MatchDir :: TopToBottom) } # [doc = " Matches the full state of the stack. This method will clear the stack as it evaluates."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " /// # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"aaaa\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state.stack_push(|state| state.match_string(\"a\")).and_then(|state| {"] # [doc = "     state.stack_push(|state| state.match_string(\"a\"))"] # [doc = " }).and_then(|state| state.stack_match_peek());"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 4);"] # [doc = " ```"] # [inline] pub fn stack_match_pop (mut self : Box < Self >) -> ParseResult < Box < Self > > { let mut position = self . position ; let mut result = true ; while let Some (span) = self . stack . pop () { result = position . match_string (span . as_borrowed_or_rc () . as_str ()) ; if ! result { break ; } } if result { self . position = position ; Ok (self) } else { Err (self) } } # [doc = " Drops the top of the stack. Returns `Ok(Box<ParserState>)` if there was a value to drop, or"] # [doc = " `Err(Box<ParserState>)` otherwise."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"aa\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state.stack_push(|state| state.match_string(\"a\")).and_then("] # [doc = "     |state| state.stack_drop()"] # [doc = " );"] # [doc = " assert!(result.is_ok());"] # [doc = " assert_eq!(result.unwrap().position().pos(), 1);"] # [doc = " ```"] # [inline] pub fn stack_drop (mut self : Box < Self >) -> ParseResult < Box < Self > > { match self . stack . pop () { Some (_) => Ok (self) , None => Err (self) , } } # [doc = " Restores the original state of the `ParserState` when `f` returns an `Err`. Currently,"] # [doc = " this method only restores the stack."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use pest;"] # [doc = " # #[allow(non_camel_case_types)]"] # [doc = " # #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]"] # [doc = " enum Rule {}"] # [doc = ""] # [doc = " let input = \"ab\";"] # [doc = " let mut state: Box<pest::ParserState<'_, Rule>> = pest::ParserState::new(input);"] # [doc = " let mut result = state.restore_on_err(|state| state.stack_push(|state|"] # [doc = "     state.match_string(\"a\")).and_then(|state| state.match_string(\"a\"))"] # [doc = " );"] # [doc = ""] # [doc = " assert!(result.is_err());"] # [doc = ""] # [doc = " // Since the the rule doesn't match, the \"a\" pushed to the stack will be removed."] # [doc = " let catch_panic = std::panic::catch_unwind(|| result.unwrap_err().stack_pop());"] # [doc = " assert!(catch_panic.is_err());"] # [doc = " ```"] # [inline] pub fn restore_on_err < F > (self : Box < Self > , f : F) -> ParseResult < Box < Self > > where F : FnOnce (Box < Self >) -> ParseResult < Box < Self > > , { match f (self . checkpoint ()) { Ok (state) => Ok (state . checkpoint_ok ()) , Err (state) => Err (state . restore ()) , } } # [inline] pub (crate) fn checkpoint (mut self : Box < Self >) -> Box < Self > { self . stack . snapshot () ; self } # [inline] pub (crate) fn checkpoint_ok (mut self : Box < Self >) -> Box < Self > { self . stack . clear_snapshot () ; self } # [inline] pub (crate) fn restore (mut self : Box < Self >) -> Box < Self > { self . stack . restore () ; self } }
